            p = w.get("path")
            if isinstance(p, str):
                paths.add(p)
    return paths

def collect_pre_paths(pre):
    paths = set()
    if isinstance(pre, dict):
        for k, v in pre.items():
            if isinstance(k, str) and k.startswith("/testbed/"):
                paths.add(k)
            if isinstance(v, (dict, list)):
                paths |= collect_pre_paths(v)
    elif isinstance(pre, list):
        for item in pre:
            paths |= collect_pre_paths(item)
    return paths

def apply_writes(pre, writes):
    fs = {}
    if isinstance(pre, dict):
